using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CorruptedEnhanceEffect", menuName = "Data/Battle/Effects/Enemy/CorruptedEnhance Effect")]
public class CorruptedEnhanceEffect : Effect
{
	[SerializeField]
	private int newCorruptionValue;

	public int NewCorruptionValue => newCorruptionValue;

	protected override string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		return GetEffectDescriptionWithAmountReplacedWithX(localizedDescription, GetNumberToReplaceWithX(), newCorruptionValue);
	}

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return Smart.Format(GetLocalizedDescription(), amount, newCorruptionValue);
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		effectOwner.GetComponent<UnitEffects>().IsEffectActiveGetEffectInstance(this).PlayBlinkingFeedback();
	}
}
